style.css:
@-moz-document domain("roblox.com") {
/* Set background on the whole body */
  body {
    background: url("https://i.pinimg.com/736x/ab/1f/6b/ab1f6b585ffcc468085e0d94dd95f014.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
    height: 100% !important;
    overflow: hidden !important;
  }

  /* Add some transparency to Roblox's main content if you want */
  .container-main, #container-main {
    background-color: rgba(255, 255, 255, 0.7) !important;
    border: none !important;
  }

  /* Remove white flash behind the body (optional) */
  .background-cover {
    display: none !important;
  }
}
